	/** 
	 * jumpstart the process by instantiating2 Seller
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		sellerId = SellerService.getSellerInstance()
		.createSeller( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		SellerService.getSellerInstance()
				.createSeller( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.sellerSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Seller : " + successValue.getSellerId());
							  if (successValue.getSellerId().equals(sellerId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfSellerList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Seller test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on seller consumed")
					);
			subscriber.sellerSubscribe( sellerId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Seller : " + successValue.getSellerId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfSellerList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on seller for sellerId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Seller. 
	 */
	protected Seller read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Seller" );

		Seller entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Seller with primary key" );
		msg.append( sellerId );
		
		SellerFetchOneSummary fetchOneSummary = new SellerFetchOneSummary( sellerId );

		try {
			entity = SellerService.getSellerInstance().getSeller( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Seller " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Seller.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Seller." );

		StringBuilder msg = new StringBuilder( "Failed to update a Seller : " );        
		Seller entity = read();
		UpdateSellerCommand command = generateUpdateCommand();
		command.setSellerId(entity.getSellerId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Seller." );

			// for use later on...
			sellerId = entity.getSellerId();

			SellerService proxy = SellerService.getSellerInstance();  

			proxy.updateSeller( command ).get();

			LOGGER.info( "-- Successfully saved Seller - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + sellerId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Seller.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Seller." );

		Seller entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Seller with id " + sellerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Seller with id " + sellerId );

			throw e;
		}

		try{
			SellerService.getSellerInstance().delete( new DeleteSellerCommand( entity.getSellerId() ) ).get();
			LOGGER.info( "-- Successfully deleted Seller with id " + sellerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Seller with id " + sellerId );

			throw e;
		}
	}

	/**
	 * get all Sellers.
	 */
	protected List<Seller> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Sellers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Seller : " );        
		List<Seller> collection  = new ArrayList<>();

		try {
			// call the static get method on the SellerService
			collection = SellerService.getSellerInstance().getAllSeller();
			assertNotNull( collection, "An Empty collection of Seller was incorrectly returned.");
			
			// Now print out the values
			Seller entity = null;            
			Iterator<Seller> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getSellerId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

